-- Synthetic examples only: never inserted into participants/tests or research_data.
create table private.research_demo (
 id text primary key, name text not null, cohort text not null,
 is_demo boolean not null default true check (is_demo),
 results jsonb not null
);
revoke all on private.research_demo from public, anon, authenticated;
create function public.research_demo_data(passcode text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
 if not private.check_passcode(passcode) then
   raise exception 'forbidden' using errcode = '42501';
 end if;
 return coalesce((select jsonb_agg(to_jsonb(d) order by d.id) from private.research_demo d), '[]'::jsonb);
end;
$$;
revoke all on function public.research_demo_data(text) from public;
grant execute on function public.research_demo_data(text) to anon, authenticated;
